101	/// What [`decide`] said of one component, kept on its entry so that every merge of the checker's props into it lists by
102	/// the same decision ([`narrow`]): the decision is made once, from the structural answer's evidence.
103	#[derive(Debug, Clone, Default, PartialEq, Eq)]
104	pub struct Placement {
105	    /// The members evidence leaves out of the listing ([`Shown::collapsed`] and [`Shown::used`]), by name under the
106	    /// source the structural answer gives each, sources in order and each source's names sorted: a listed prop is left
107	    /// out only when both match, so a prop of another source with the same name, or one the structural answer gave no
108	    /// source, is never hidden by it. Only sources outside the project are held, the only ones [`narrow`] moves from,
109	    /// and each source's type name and path once per component, not once per name.
110	    left: Vec<(Source, Box<[Box<str>]>)>,
111	    /// The members of `left` named in their layer's `used` list.
112	    used: BTreeSet<String>,
113	}
114	
115	impl Placement {
116	    /// Whether the decision leaves `name`, declared by `parent`, out of the listing.
117	    fn leaves(&self, name: &str, parent: &PropParent) -> bool {
118	        let source = (parent.name.as_str(), parent.file_name.as_str());
119	        self.left
120	            .binary_search_by(|((type_name, file_name), _)| (type_name.as_str(), file_name.as_str()).cmp(&source))
121	            .ok()
122	            .and_then(|at| self.left.get(at))
123	            .is_some_and(|(_, names)| names.binary_search_by(|held| (**held).cmp(name)).is_ok())
124	    }
125	}
126	
127	/// Lists `entry` by its kept [`Placement`]: a listed prop (in `props` or `notableInherited`) the decision leaves out
128	/// and that a source outside the project declares (a dependency's, or React's and the DOM's) moves to the layer of
129	/// its source, as a name, when the placement left out that name from that same source. Its home is the layer of its
130	/// `parent` (by type name and file), else, for an ambient source, the entry's HTML element layer, else a new layer of
131	/// its `parent`. A prop with no `parent` has no known source and stays listed: no name is ever lost. Then each
132	/// layer's `used` list is written. Without a placement (no evidence was gathered) nothing changes. Run by [`apply`] and at the end of each merge of the
133	/// checker's props, which may list again what the structural answer left out.
134	pub(crate) fn narrow(entry: &mut ComponentEntry) {
135	    let Some(placement) = entry.relevance.clone() else { return };
136	    let ComponentEntry { props, notable_inherited, inheritance, .. } = entry;
137	    for listing in [props, notable_inherited] {
138	        listing.retain(|name, prop| {
139	            let Some(parent) = prop.parent.as_ref() else { return true };
140	            if !placement.leaves(name, parent) {
141	                return true;
142	            }
143	            // Only a source outside the project is narrowed: a dependency's or an ambient one, decided by the
144	            // declaring path. The project's own sources stay as the collapse rule lists them.
145	            if crate::origin::declaration_origin(&parent.file_name) == crate::origin::Origin::Project {
146	                return true;
147	            }
148	            // Each name is held once: a layer already holding it keeps it (`listed_props_leave_layers`' rule).
149	            if !inheritance.iter().any(|layer| layer.members.contains(name)) {
150	                home(inheritance, parent).members.push(name.clone());
151	            }
152	            false
153	        });
154	    }
155	    for layer in inheritance.iter_mut() {
156	        layer.total_props = layer.total_props.max(u32::try_from(layer.members.len()).unwrap_or(u32::MAX));
157	        layer.used = layer.members.iter().filter(|name| placement.used.contains(*name)).cloned().collect();
158	    }
159	}
160	
161	/// The layer a prop declared in `parent` is left in ([`narrow`]): made when the entry has none.
162	fn home<'l>(layers: &'l mut Vec<InheritedLayer>, parent: &PropParent) -> &'l mut InheritedLayer {
163	    let ambient = crate::origin::declaration_origin(&parent.file_name).is_ambient();
164	    let at = layers
165	        .iter()
166	        .position(|layer| layer.type_name == parent.name && layer.file_name == parent.file_name)
167	        .or_else(|| {
168	            ambient
169	                .then(|| {
170	                    layers.iter().position(|layer| {
171	                        layer.html_element.is_some() && crate::origin::declaration_origin(&layer.file_name).is_ambient()
172	                    })
173	                })
174	                .flatten()
175	        });
176	    let at = at.unwrap_or_else(|| {
177	        layers.push(InheritedLayer {
178	            type_name: parent.name.clone(),
179	            file_name: parent.file_name.clone(),
180	            omitted: Vec::new(),
181	            html_element: None,
182	            total_props: 0,
183	            members: Vec::new(),
184	            used: Vec::new(),
185	        });
186	        layers.len() - 1
187	    });
188	    &mut layers[at]
189	}
