191	/// Everything known about the members one component's props type reaches.
192	#[derive(Debug, Clone, Copy)]
193	pub(crate) struct Evidence<'a> {
194	    /// The members, in the order the props type reaches them; [`Shown`] keeps this order. A name repeated is placed
195	    /// once, by its first member.
196	    pub(crate) members: &'a [Member],
197	    /// What the component's own function body does with its props; `None` when it has no function of its own.
198	    pub(crate) body: Option<&'a Body>,
199	    /// The props passed at the component's JSX call sites across the project.
200	    pub(crate) call_sites: &'a CallSites,
201	}
202	
203	/// One member the props type reaches, with the signals its declaration gives.
204	#[derive(Debug, Clone, Default, PartialEq, Eq)]
205	pub(crate) struct Member {
206	    /// The member's name. Only compared with other names in the same [`Evidence`], never with a list.
207	    pub(crate) name: String,
208	    /// The props type declares it itself, not through an inherited source.
209	    pub(crate) own: bool,
210	    /// A key a `Pick<X, …>` names.
211	    pub(crate) picked: bool,
212	    /// It redeclares or narrows a base member.
213	    pub(crate) overrides: bool,
214	    /// It is not optional.
215	    pub(crate) required: bool,
216	    /// Its declaration carries a `@default` tag.
217	    pub(crate) default_tag: bool,
218	    /// It carries a JSDoc comment: orders the rows, never shows a member.
219	    pub(crate) documented: bool,
220	    /// Its type is a union of literals: orders the rows, never shows a member.
221	    pub(crate) literal_union: bool,
222	    /// Declared by React's or the shared DOM declarations ([`crate::origin::Origin::is_ambient`]): decided by
223	    /// the declaring path, never by the name.
224	    pub(crate) ambient: bool,
225	}
