298	/// Where [`decide`] puts each member, every list in the order of [`Evidence::members`], except that `rows` puts the
299	/// documented and literal-union members first.
300	#[derive(Debug, Clone, Default, PartialEq, Eq)]
301	pub(crate) struct Shown {
302	    /// Typed rows.
303	    pub(crate) rows: Vec<String>,
304	    /// Ambient members named in their collapsed layer's `used` list: passed at the floor or read.
305	    pub(crate) used: Vec<String>,
306	    /// Members left in their collapsed layer.
307	    pub(crate) collapsed: Vec<String>,
308	    /// Members with no signal whose body evidence is incomplete or absent: listed or collapsed by the collapse rule
309	    /// alone, so missing evidence never hides more than that rule does.
310	    pub(crate) unknown: Vec<String>,
311	}
312	
313	/// Decides, from the evidence alone, where each member of a component's props goes.
314	pub(crate) fn decide(evidence: &Evidence<'_>) -> Shown {
315	    let body = evidence.body;
316	    let complete = body.is_some_and(Body::is_complete);
317	    let reads: BTreeSet<&str> = body.map(|body| body.reads.iter().map(String::as_str).collect()).unwrap_or_default();
318	    let forwarded = body.map(Body::forwarded).unwrap_or_default();
319	    let at_floor: BTreeSet<&str> = evidence
320	        .call_sites
321	        .passed
322	        .iter()
323	        .filter(|(_, count)| evidence.call_sites.at_floor(*count))
324	        .map(|(name, _)| name.as_str())
325	        .collect();
326	    let mut shown = Shown::default();
327	    let mut ordered_rows = Vec::new();
328	    let mut placed = BTreeSet::new();
329	    for member in evidence.members {
330	        let name = member.name.as_str();
331	        if !placed.insert(name) {
332	            continue;
333	        }
334	        let declared = member.own || member.picked || member.overrides || member.required || member.default_tag;
335	        // Passed at the floor puts a member forward as a typed row, ambient or not: consumers set it, so a story needs
336	        // its control. Read or forwarded puts a non-ambient member forward as a row; an ambient member the body only
337	        // reads is a name in its layer's `used` list (ADR 0028, Combination).
338	        let passed = at_floor.contains(name);
339	        let read = reads.contains(name);
340	        let list = if declared || passed || (!member.ambient && (read || forwarded.contains(name))) {
341	            ordered_rows.push((!(member.documented || member.literal_union), member.name.clone()));
342	            continue;
343	        } else if member.ambient && read {
344	            &mut shown.used
345	        } else if !complete && !member.ambient {
346	            // The body's silence is unknown: listed or collapsed as the collapse rule alone says. An ambient member
347	            // (React's and the DOM's attributes, which every element has) is never listed for want of evidence: it
348	            // stays a name in its layer, so a component without call sites lists no hundreds of DOM attributes.
349	            &mut shown.unknown
350	        } else {
351	            &mut shown.collapsed
352	        };
353	        list.push(member.name.clone());
354	    }
355	    ordered_rows.sort_by_key(|(plain, _)| *plain);
356	    shown.rows = ordered_rows.into_iter().map(|(_, name)| name).collect();
357	    shown
358	}
359	
360	impl Body {
361	    /// Whether the body's evidence is complete, so that a prop it never mentions is known to be unused: nothing handed
362	    /// on, and no spread of the props onto a tag that did not resolve. What an incomplete body does say (a read, a
363	    /// default, a forward) is still certain; only its silence is unknown.
364	    fn is_complete(&self) -> bool {
365	        !self.handed_on
366	            && !self.elements.iter().any(|element| {
367	                element.target == Target::Unresolved
368	                    && element.attributes.iter().any(|attribute| attribute.spreads_props())
369	            })
370	    }
371	
372	    /// The props a spread of the props object or a rest binding passes one hop on to a component: the component's own
373	    /// props, minus those an attribute after the spread fixes. Spreads onto DOM tags pass nothing.
374	    fn forwarded(&self) -> BTreeSet<&str> {
375	        let mut forwarded = BTreeSet::new();
376	        for element in &self.elements {
377	            let Target::Component(own) = &element.target else { continue };
378	            for (at, attribute) in element.attributes.iter().enumerate() {
379	                if !attribute.spreads_props() {
380	                    continue;
381	                }
382	                let fixed: BTreeSet<&str> = element.attributes[at + 1..]
383	                    .iter()
384	                    .filter_map(|after| match after {
385	                        Attribute::Named(name) => Some(name.as_str()),
386	                        Attribute::Spread(_) => None,
387	                    })
388	                    .collect();
389	                forwarded.extend(own.iter().map(String::as_str).filter(|name| !fixed.contains(name)));
390	            }
391	        }
392	        forwarded
393	    }
394	}
395	
396	impl Attribute {
397	    /// Whether the attribute spreads the props object or a rest binding of it.
398	    fn spreads_props(&self) -> bool {
399	        matches!(self, Self::Spread(SpreadOf::Props | SpreadOf::Rest))
400	    }
401	}
