403	#[cfg(test)]
404	mod tests {
405	    use super::*;
406	
407	    /// Where a member went, for the tables.
408	    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
409	    enum Placed {
410	        Row,
411	        Used,
412	        Collapsed,
413	        Unknown,
414	    }
415	
416	    fn inherited(name: &str) -> Member {
417	        Member { name: name.to_owned(), ..Member::default() }
418	    }
419	
420	    fn ambient(name: &str) -> Member {
421	        Member { ambient: true, ..inherited(name) }
422	    }
423	
424	    fn strings(names: &[&str]) -> Vec<String> {
425	        names.iter().map(|name| (*name).to_owned()).collect()
426	    }
427	
428	    fn reading(names: &[&str]) -> Body {
429	        Body { reads: strings(names), ..Body::default() }
430	    }
431	
432	    fn named(name: &str) -> Attribute {
433	        Attribute::Named(name.to_owned())
434	    }
435	
436	    fn element(target: Target, attributes: Vec<Attribute>) -> Element {
437	        Element { target, attributes }
438	    }
439	
440	    /// The evidence of one case, owned: [`Evidence`] borrows it.
441	    #[derive(Default)]
442	    struct Owned {
443	        members: Vec<Member>,
444	        body: Option<Body>,
445	        call_sites: CallSites,
446	    }
447	
448	    impl Owned {
449	        fn decide(&self) -> Shown {
450	            decide(&Evidence { members: &self.members, body: self.body.as_ref(), call_sites: &self.call_sites })
451	        }
452	    }
453	
454	    fn with(members: Vec<Member>, body: Option<Body>) -> Owned {
455	        Owned { members, body, ..Owned::default() }
456	    }
457	
458	    fn placed(shown: &Shown, name: &str) -> Option<Placed> {
459	        let lists = [
460	            (&shown.rows, Placed::Row),
461	            (&shown.used, Placed::Used),
462	            (&shown.collapsed, Placed::Collapsed),
463	            (&shown.unknown, Placed::Unknown),
464	        ];
465	        lists.into_iter().find(|(list, _)| list.iter().any(|n| n == name)).map(|(_, placed)| placed)
466	    }
467	
468	    /// One case of a table: its label, its evidence, and where each named member must go.
469	    type Case<'a> = (&'a str, Owned, &'a [(&'a str, Placed)]);
470	
471	    /// Runs each case and checks where every named member went.
472	    fn table(cases: Vec<Case<'_>>) {
473	        for (case, evidence, expected) in cases {
474	            let shown = evidence.decide();
475	            for (name, want) in expected {
476	                assert_eq!(placed(&shown, name), Some(*want), "{case}: {name}");
477	            }
478	        }
479	    }
480	
481	    #[test]
482	    fn an_inherited_member_the_body_never_reads_stays_in_its_layer() {
483	        let evidence = with(vec![inherited("tone"), inherited("size")], Some(reading(&["size"])));
484	        let shown = evidence.decide();
485	        assert_eq!(shown.collapsed, ["tone"]);
486	        assert_eq!(shown.rows, ["size"]);
487	    }
488	
489	    #[test]
490	    fn a_member_the_props_type_declares_itself_is_always_a_row() {
491	        let own = |member: Member| Member { own: true, ..member };
492	        table(vec![
493	            ("never read", with(vec![own(inherited("a"))], Some(Body::default())), &[("a", Placed::Row)]),
494	            ("unknown body", with(vec![own(inherited("a"))], None), &[("a", Placed::Row)]),
495	            ("ambient", with(vec![own(ambient("a"))], Some(Body::default())), &[("a", Placed::Row)]),
496	        ]);
497	    }
